const domain = $env.COMPANY_DOMAIN || 'example.com';
const criticalPages = [
  '/',
  '/products',
  '/pricing',
  '/blog',
  '/contact',
  '/signup'
];

return criticalPages.map(page => ({
  json: {
    url: `https://${domain}${page}`,
    page_path: page
  }
}));

const mobileResult = $node['PageSpeed (Mobile)'].json;
const desktopResult = $node['PageSpeed (Desktop)'].json;
const pageInfo = $node['Define Pages'].json;

function extractMetrics(result) {
  const lhr = result.lighthouseResult || {};
  const audits = lhr.audits || {};

  return {
    performance_score: Math.round((lhr.categories?.performance?.score || 0) * 100),
    lcp: {
      value_ms: audits['largest-contentful-paint']?.numericValue || 0,
      score: audits['largest-contentful-paint']?.score || 0,
      display: audits['largest-contentful-paint']?.displayValue || 'N/A'
    },
    fid: {
      value_ms: audits['max-potential-fid']?.numericValue || 0,
      score: audits['max-potential-fid']?.score || 0,
      display: audits['max-potential-fid']?.displayValue || 'N/A'
    },
    cls: {
      value: audits['cumulative-layout-shift']?.numericValue || 0,
      score: audits['cumulative-layout-shift']?.score || 0,
      display: audits['cumulative-layout-shift']?.displayValue || 'N/A'
    },
    inp: {
      value_ms: audits['interaction-to-next-paint']?.numericValue || 0,
      score: audits['interaction-to-next-paint']?.score || 0,
      display: audits['interaction-to-next-paint']?.displayValue || 'N/A'
    },
    ttfb: {
      value_ms: audits['server-response-time']?.numericValue || 0,
      display: audits['server-response-time']?.displayValue || 'N/A'
    },
    fcp: {
      value_ms: audits['first-contentful-paint']?.numericValue || 0,
      display: audits['first-contentful-paint']?.displayValue || 'N/A'
    },
    tbt: {
      value_ms: audits['total-blocking-time']?.numericValue || 0,
      display: audits['total-blocking-time']?.displayValue || 'N/A'
    },
    speed_index: {
      value_ms: audits['speed-index']?.numericValue || 0,
      display: audits['speed-index']?.displayValue || 'N/A'
    }
  };
}

const mobile = extractMetrics(mobileResult);
const desktop = extractMetrics(desktopResult);

// Determine overall status
let status = 'good';
const issues = [];

// LCP thresholds: Good < 2.5s, Needs Improvement < 4s, Poor >= 4s
if (mobile.lcp.value_ms > 4000) { status = 'poor'; issues.push(`Mobile LCP: ${mobile.lcp.display} (poor, target <2.5s)`); }
else if (mobile.lcp.value_ms > 2500) { if (status !== 'poor') status = 'needs_improvement'; issues.push(`Mobile LCP: ${mobile.lcp.display} (needs improvement)`); }

// CLS thresholds: Good < 0.1, Needs Improvement < 0.25, Poor >= 0.25
if (mobile.cls.value > 0.25) { status = 'poor'; issues.push(`Mobile CLS: ${mobile.cls.display} (poor, target <0.1)`); }
else if (mobile.cls.value > 0.1) { if (status !== 'poor') status = 'needs_improvement'; issues.push(`Mobile CLS: ${mobile.cls.display} (needs improvement)`); }

// TBT (proxy for FID/INP): Good < 200ms, Poor > 600ms
if (mobile.tbt.value_ms > 600) { status = 'poor'; issues.push(`Mobile TBT: ${mobile.tbt.display} (poor, target <200ms)`); }
else if (mobile.tbt.value_ms > 200) { if (status !== 'poor') status = 'needs_improvement'; issues.push(`Mobile TBT: ${mobile.tbt.display} (needs improvement)`); }

return [{
  json: {
    url: pageInfo.url,
    page_path: pageInfo.page_path,
    mobile: mobile,
    desktop: desktop,
    status: status,
    issues: issues,
    has_issues: issues.length > 0,
    checked_at: new Date().toISOString()
  }
}];

